\label{thm:allmean}
	For every sequence $n\to\infty$ and $m=m_n\to\infty$,
	\begin{align}\label{eq:allmean}
		\operatorname{\mathds{E}} T_{n,m}-m
		=(1+o(1))\left(\log n\,\log(\min\{m,\log n\})+\frac{\pi}{\sqrt2}\sqrt{m\log n}\right).
	\end{align}
	In particular, we have
	\[
		\operatorname{\mathds{E}} T_{n,m}-m\sim
		\begin{cases}
			(\log n)\,(\log m),      & m\ll (\log n)(\log\log n)^2,                        \\[1mm]
			\left(1+\pi\sqrt{c/2}\right)\log n\,\log\log n,
			                     & m\sim c\,(\log n)(\log\log n)^2,\quad c\in(0,\infty), \\[1mm]
			\pi\sqrt{m\log n/2}, & m\gg (\log n)(\log\log n)^2.
		\end{cases}
	\]

\label{thm:clt}
	Let $m=m_n\geqslant 1$ be arbitrary and write $\mu_{n,m}:=\operatorname{\mathds{E}} T_{n,m}=\operatorname{\mathds{E}} S_{n,m}$.
	As $n\to\infty$,
	\begin{enumeratea}
		\item \label{clt:a}$(S_{n,m}-\mu_{n,m})/\sqrt{\mu_{n,m}}\to 0$ in $L^2$.
		In particular, $S_{n,m}/\mu_{n,m}\to 1$ in $L^2$.
		\item \label{clt:b}$(T_{n,m}-S_{n,m})/\sqrt{\mu_{n,m}} \implies \operatorname{N} (0,1)$.
		\item \label{clt:c} $\operatorname{Var}(T_{n,m}) \sim \mu_{n,m}$ and
		\[
			\frac{T_{n,m}-\mu_{n,m}}{\sqrt{\mu_{n,m}}}\implies \operatorname{N}(0,1).
		\]
        \item\label{clt:d} Let $d_K$ denote the Kolmogorov--Smirnov distance.
	There exist absolute constants $C,C',n_0$ such that, for $n\geqslant n_0$, we have
	\begin{align}\label{eq:uniformrate}
    \begin{split}    
		\sup_{m\geqslant1}d_K &\left(\frac{T_{n,m}-\operatorname{\mathds{E}} T_{n,m}}{\sqrt{\mu_{n,m}}},\operatorname{N}(0,1)\right)\\ 
        &\leqslant C\left(\frac{\log(2+\mu_{n,m})}{\sqrt{\mu_{n,m}}}
		+\left(\frac{1+\operatorname{Var}(S_{n,m})}{\mu_{n,m}^2}+\frac1{n^2}\right)^{1/5} +\left( \frac{\operatorname{Var}(S_{n,m})}{\mu_{n,m}}\right)^{1/3}\right)\\
        &\leqslant C' \cdot \frac{(1+\log\log n)^{2/3}}{(\log n)^{1/3}}.
            \end{split}
	\end{align}
	\end{enumeratea}

\label{rem:weaker}
	On the way to Theorem~\ref{thm:var}, we prove two further bounds on $\operatorname{Var}(S_{n,m})$, which complement Theorem~\ref{thm:var}.
	\begin{enumeratea}
		\item \emph{Universal bound.} There is a universal constant $C<\infty$ such that for all $n\geqslant 2$ and $m\geqslant 1$,
		\begin{align}\label{eq:varSuniv}
			\operatorname{Var}(S_{n,m})\leqslant C m.
		\end{align}
		This estimate holds for every $n\geqslant2$.
		For large multiplicities, Theorem~\ref{thm:var} improves its $m$ term by a factor of $\log n$.
		Together with $\mu_{n,m}\geqslant m-1+\mathcal{H}_n$, it gives
		$\operatorname{Var}(S_{n,m})/\mu_{n,m}^2\leqslant C/\mathcal{H}_n$.
		That bound proves the compensator law of large numbers and the martingale CLT for every $m$.
		It also proves the score CLT when $m=o(\log n)$.
		Section~\ref{ssec:univ} gives a short proof.

		\item \emph{Logarithmic multiplicity.} For every $\lambda>0$ there exist $C_\lambda<\infty$ and $n_0(\lambda)$ such that for all $n\geqslant n_0(\lambda)$ and all $1\leqslant m\leqslant \lambda\log n$,
		\begin{align}\label{eq:varSlog}
			\operatorname{Var}(S_{n,m})\leqslant C_\lambda\bigl(1+\log m\bigr)^2.
		\end{align}
		This bound retains the dependence on $m$.
		It gives $\operatorname{Var}(S_{n,m})=O(1)$ for fixed $m$.
		Section~\ref{ssec:logregime} proves it and uses it in Theorem~\ref{thm:var}.
	\end{enumeratea}

\label{lem:meanintegral}
	For every $n,m\geqslant1$,
	\begin{align}\label{eq:meanintegral}
		\operatorname{\mathds{E}} T_{n,m}=\int_0^1\frac1p{\operatorname{\mathds{E}} Z(p)}\,dp,
		\quad
		\operatorname{\mathds{E}} T_{n,m}-m=\int_0^1\frac1p(\operatorname{\mathds{E}} Z(p)-mp)\,dp.
	\end{align}

\label{lem:earlymean}
	With absolute implied constants,
	\begin{align}\label{eq:earlymean}
		I_{n,m}=\begin{cases}
			        (\log n)\mathcal{H}_m+O(m),           & m\leqslant \log n, \\
			        (\log n)\log\log n+O(\log n), & m\geqslant \log n.
		        \end{cases}
	\end{align}

\label{lem:bulkmean}
	As $n\to\infty$, if $m/\log n\to\infty$, then
	\begin{align}\label{eq:bulkmean}
		J_{n,m}\sim\frac{\pi}{\sqrt2}\sqrt{m\log n}.
	\end{align}
	If $1\leqslant m/\log n\leqslant R$ for a fixed $R$, then $0\leqslant J_{n,m}\leqslant C_R \log n$.

\label{lem:easylb}
	For every $n,m\geqslant1$,
	$\operatorname{\mathds{E}} S_{n,m}\geqslant\mathcal{H}_n+m-1$.

\label{cor:capacitycomparisons}
	For fixed $n,t$, the maximum of independent $\operatorname{Bin}(m,1/2)$ variables conditionally on their sum being $t$ is stochastically nondecreasing in every admissible capacity $m$.
	Moreover, if $$(Z_1(t),Z_2(t),\ldots,Z_n(t))\sim\operatorname{Multinomial}(t;1/n,1/n,\ldots,1/n),
    $$ 
    then
    \begin{align}\label{eq:multcomparison}
		W_t^{(m)}\leqslant_{\mathrm{st}}\max_i Z_i(t),\quad t\leqslant nm.
	\end{align}
	In particular, for integers $k\geqslant1$,
	\begin{align}\label{eq:multmaxbound}
		\operatorname{\mathds{P}}(W_t^{(m)}\geqslant k)\leqslant n\left(\frac{et}{nk}\right)^k.
	\end{align}

\label{lem:elastj}
	Let $\rho_1:=\sqrt{\rho_0}$ and $\rho_2:=(1+\rho_1)/2$. For $n\geqslant n_0(\lambda)$, $m\geqslant1$, $1\leqslant j\leqslant m$ and all $j\leqslant s\leqslant \rho_1 nj$,
	\[
		\phi_j(s)=\frac{h_s(j)}{p_j(s)}\ \geqslant\ 1-\rho_2.
	\]
	Consequently, with $\beta_j:=(1-\rho_2)\,j$, for all $0\leqslant t<t'\leqslant \rho_1 nj$,
	\begin{align}\label{eq:elastj}
		p_j(t)\leqslant p_j(t')\bigl(\frac{t+1}{t'+1}\bigr)^{\beta_j}.
	\end{align}

\label{lem:stirling}
	Let $n\geqslant 3$, $1\leqslant k\leqslant m-1$, and let $t$ be an integer with $1\leqslant t-k\leqslant N-m-1$ and $\mu:=t/n\leqslant k$. Then
	\begin{align}\label{eq:hstirling}
		h_t(k)\ \geqslant\ \frac{e^{-\Lambda_t(k)}}{7\sqrt{k(1-k/m)}}.
	\end{align}
	Moreover, if in addition $k-\mu\leqslant (n-1)\mu/2$, then
	\begin{align}
		\Lambda_t(k) & \leqslant (k-\mu)^2\biggl(\frac1\mu+\frac{1}{m-k}\biggr), \label{eq:LamF1}\text{ and } \\
		\Lambda_t(k) & \leqslant \frac{(k-\mu)^2}{\mu}+2(k-\mu). \label{eq:LamF2}
	\end{align}

\label{lem:elastG}
	Let $n\geqslant 3$, $1\leqslant j\leqslant m-1$, and let $s$ be an integer with $j\leqslant s\leqslant nj$. Write $\mu:=s/n$ and $d:=j-\mu\geqslant0$. Then
	\begin{align}\label{eq:phiG}
		\phi_j(s)=\frac{h_s(j)}{p_j(s)}\ \geqslant\ 1-r_j(s)\ \geqslant\ \frac{m\,(d-1/n)}{(j+1)(m-\mu)}.
	\end{align}
	Consequently, for $n\geqslant n_0$, $m\geqslant1$, $2\log n\leqslant j\leqslant m-1$ and all integers $j\leqslant s\leqslant n(j-D_j/2)$,
	\begin{align}\label{eq:betaG}
		j\phi_j(s)\geqslant\beta_j:=\frac{m(D_j/2-1/n)}{2(m-j+D_j/2)},\text{ and } \frac{1}{60}\sqrt{j\log n}\leqslant \beta_j\leqslant\min\biggl(t_j,\frac{3j}{2}\biggr).
	\end{align}
	In particular, for all $0\leqslant t<t'\leqslant n(j-D_j/2)$,
	\begin{align}\label{eq:elastG}
		p_j(t)\leqslant p_j(t')\biggl(\frac{t+1}{t'+1}\biggr)^{\beta_j}.
	\end{align}
